const priorities={soil:{fit:82,text:'Strong nitrogen contribution and a favorable fit for projected summer moisture.'},water:{fit:76,text:'A lower water-demand path with cover retained through the driest window.'},risk:{fit:88,text:'Diversified timing and drought-tolerant crops reduce exposure to seasonal volatility.'}};
document.querySelectorAll('.priority').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.priority').forEach(b=>b.classList.remove('active'));button.classList.add('active');const choice=priorities[button.dataset.key];document.querySelector('#fit').innerHTML=choice.fit+'<span>/100</span>';document.querySelector('#meter').style.width=choice.fit+'%';document.querySelector('#outcome-text').textContent=choice.text;}));
document.querySelectorAll('.crop').forEach(crop=>crop.addEventListener('click',()=>{document.querySelectorAll('.crop').forEach(c=>c.classList.remove('selected'));crop.classList.add('selected');document.querySelector('#outcome-text').textContent=`${crop.dataset.crop} selected as a rotation step. Recalculate to compare its field fit.`;}));
document.querySelector('#recalculate').addEventListener('click',e=>{const f=document.querySelector('#fit');e.currentTarget.textContent='Path updated ✓';setTimeout(()=>e.currentTarget.innerHTML='Recalculate path <span>↗</span>',1300);f.animate([{transform:'translateY(3px)',opacity:.45},{transform:'translateY(0)',opacity:1}],{duration:350});});
